function describeUrl(str) {
  const u = new URL(str);
  const scheme = u.protocol.replace(":", "");
  const defaults = { http: 80, https: 443 };
  return {
    scheme,
    host: u.hostname,
    port: u.port ? Number(u.port) : defaults[scheme],
    path: u.pathname,
    query: Object.fromEntries(u.searchParams),
    fragmentSentToServer: false, // the #fragment never leaves the browser
  };
}

describeUrl("https://shop.example.com/cart?item=42&qty=2#reviews");
// { scheme: 'https', host: 'shop.example.com', port: 443, path: '/cart',
//   query: { item: '42', qty: '2' }, fragmentSentToServer: false }
```
